const CONFIG = {
  MEET_WHATSAPP: '91XXXXXXXXXX',
  WA_PHONE_NUMBER_ID: 'XXXXXXXXXXXXXXX',
  WA_API: 'https://graph.facebook.com/v21.0',
  SLACK_CHANNEL: 'C0AKT2RDQNA',
  MODEL_FAST: 'claude-haiku-4-5-20251001'
};
const q = $json.query || {};
const b = $json.body || {};
return [{ json: { CONFIG, escId: String(q.esc || ''), speech: String(b.SpeechResult || '').trim() } }];

const cfg = $('Config').first().json;
const e = $input.first().json || {};
const prompt = [
  'Meet (owner of The Empire Stays) just answered a phone call from Jarvis by voice. Speech-to-text may contain errors.',
  'Pending item: ' + (e.summary || 'unknown') + '. Maya\'s suggested reply to the guest: ' + (e.draft_reply || '(none)') + '.',
  'Meet said: "' + cfg.speech + '"',
  'Return one JSON object only: {"decision":"approve"|"reject"|"custom"|"unclear", "custom_reply": string|null, "spoken_confirmation": string}',
  'custom_reply = the final guest-facing WhatsApp message in Maya\'s warm voice when Meet dictates something different.',
  'spoken_confirmation = one short sentence Jarvis says back to Meet.'
].join('\n');
return [{ json: { found: !!e.id, claudeRequest: { model: cfg.CONFIG.MODEL_FAST, max_tokens: 500, messages: [{ role: 'user', content: prompt }] } } }];

const cfg = $('Config').first().json;
const C = cfg.CONFIG;
const e = $('Load escalation').first().json || {};
const url = C.WA_API + '/' + C.WA_PHONE_NUMBER_ID + '/messages';
const txt = ($input.first().json.content || []).map(c => c.text || '').join('');
let d = { decision: 'unclear', spoken_confirmation: 'Sorry, I did not get that. I have left it on your WhatsApp.' };
try { d = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (err) {}
const x = s => String(s || '').replace(/[<>&"']/g, ' ');
const out = [];
let say = d.spoken_confirmation || 'Done.';
if (!e.id) {
  say = 'That item is already closed. Nothing else to do.';
} else {
  const finalReply = d.decision === 'approve' ? e.draft_reply : (d.decision === 'custom' ? d.custom_reply : null);
  if (d.decision !== 'unclear') {
    out.push({ json: { kind: 'db', sql: "UPDATE airsynk.escalations SET status = $2, resolution = $3, final_reply = NULLIF($4, ''), resolved_at = now() WHERE id = $1", params: [e.id, d.decision === 'reject' ? 'rejected' : 'resolved', 'voice_' + d.decision, finalReply || ''] } });
  }
  if (finalReply) {
    out.push({ json: { kind: 'whatsapp', url, body: { messaging_product: 'whatsapp', to: e.phone, type: 'text', text: { body: finalReply } } } });
    out.push({ json: { kind: 'db', sql: "INSERT INTO airsynk.messages (phone, direction, body) VALUES ($1, 'out', $2)", params: [e.phone, finalReply] } });
  }
  out.push({ json: { kind: 'slack', body: { channel: C.SLACK_CHANNEL, text: '01C · ' + e.id + ' · Meet by voice: ' + d.decision + (finalReply ? ' → sent to guest' : '') } } });
}
out.push({ json: { kind: 'twiml', twiml: '<Response><Say voice="Polly.Raveena" language="en-IN">' + x(say) + '</Say></Response>' } });
return out;
